let prompt = $('Message a model3').first().json.content.parts[0].text + `

IMPORTANT ORIENTATION AND ASPECT RATIO INSTRUCTION:

Use the attached image as the visual reference/source for the generated image.

Preserve the reference image's subject, visual characteristics, style, details, and overall visual identity as appropriate.

However, the requested output aspect ratio must be treated as a native composition requirement.

Do NOT rotate the reference image or rotate the entire scene to match the requested aspect ratio.

Do NOT turn the reference sideways or upside down.

When the reference image orientation differs from the requested output orientation, naturally recompose the scene for the requested orientation while keeping all people, objects, furniture, interfaces, and environmental elements correctly oriented relative to gravity.

For a 9:16 portrait output, create a genuinely upright portrait composition. The person must remain upright, with their head above their body, and objects must maintain their normal physical orientation. Reposition, resize, crop, or rearrange elements naturally as necessary to fit the portrait canvas.

The output should look like the original scene was naturally composed for 9:16, not like the reference image was rotated or mechanically converted from landscape to portrait.

Do not sacrifice natural orientation or physical coherence in order to preserve the reference image's original framing.`;

const parts = [
  { text: prompt },
  {
    inlineData: {
        mimeType: $('Convert to Base64').first().json.parsed[0].mime,
        data: $('Convert to Base64').first().json.parsed[0].data // n8n already provides this as base64
    }
  }
];

// Return the structure ready for the API
return {
  json: {
    payload: {
      contents: [
        {
          parts: parts
        }
      ],
      generationConfig: {
          responseModalities: ["image"],
          imageConfig:{
               aspectRatio: $('Source Data').first().json.prompt_data.aspect_ratio
          }
      }
    }
  }
};

let social = $('Source Data').first().json.caption_data;
let result = [];
// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of social) {
  result.push({
    type: item.social,
    title: item.content.title,
    caption: item.content.caption,
    tags: item.content.tags,
    media_url: ["https://assets.synergizeflow.com/mediaAgentResult/mediaAgentResult-"+$('Prepare Data').first().json.agent_id+".jpg"]
  })
}

return {result: result}
